<script>
(function(){
 const menu=document.getElementById('mobileMenu');
 const nav=document.getElementById('navlinks');
 if(menu&&nav){menu.addEventListener('click',function(){const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');});nav.querySelectorAll('a').forEach(function(a){a.addEventListener('click',function(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');});});}
 document.getElementById('year').textContent=new Date().getFullYear();
 const items=document.querySelectorAll('.reveal');
 if('IntersectionObserver' in window){const observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('in-view');observer.unobserve(entry.target);}});},{threshold:.12});items.forEach(function(item){observer.observe(item);});}else{items.forEach(function(item){item.classList.add('in-view');});}
})();
</script>
